import AVFoundation
import Foundation

// MARK: - Sound packs (data only)
//
// A sound pack maps every `CosmeticEvent` to one or more bundled files
// (Resources/Sounds/<pack>/<pack>_<event>[_vN].caf, generated by
// scripts/audio/generate_sound_packs.py — see docs/cosmetics/AUDIO_MANIFEST.md).
// Several files for one event are subtle variants played round-robin; they all
// start at sample 0, so variation never shifts onset timing.
//
// File names are globally unique because Xcode copies resources flat into the
// app bundle root (the folder structure is only for humans).
//
// The default pack has no files: it is the procedural tones built into
// SoundEngine, played exactly as before the Studio existed.

struct SoundPack: Identifiable, Equatable {
    let id: String
    let displayName: String
    /// Event → bundled file names (without extension). Empty for the built-in pack.
    let files: [CosmeticEvent: [String]]

    /// The default pack: SoundEngine's synthesized tones, no files to load.
    var isBuiltIn: Bool { files.isEmpty }

    var allFileNames: [String] {
        CosmeticEvent.allCases.flatMap { files[$0] ?? [] }
    }
}

enum SoundPackCatalog {
    static let defaultPackID = CosmeticCatalog.defaultSoundPackID
    static let fileExtension = "caf"

    static let all: [SoundPack] = [
        SoundPack(id: defaultPackID, displayName: "Classic Tones", files: [:]),
        themed("quack_attack", "Quack Pack"),
        themed("purrfect_tap", "Purr Pack"),
        themed("boom_mode", "Boom Pack"),
    ]

    private static let byID: [String: SoundPack] = Dictionary(uniqueKeysWithValues: all.map { ($0.id, $0) })

    static func pack(id: String) -> SoundPack? { byID[id] }

    /// Unknown / removed pack ids resolve to the default pack (never silence).
    static func resolvedPackID(_ id: String) -> String {
        byID[id] == nil ? defaultPackID : id
    }

    /// Frequent events get three subtle variants (±3 % pitch, small timbre
    /// change) to avoid listener fatigue; the rest have one file.
    static let variantCounts: [CosmeticEvent: Int] = [.good: 3, .great: 3]

    private static func themed(_ id: String, _ name: String) -> SoundPack {
        var files: [CosmeticEvent: [String]] = [:]
        for event in CosmeticEvent.allCases {
            let count = variantCounts[event] ?? 1
            files[event] = count == 1
                ? ["\(id)_\(event.rawValue)"]
                : (1...count).map { "\(id)_\(event.rawValue)_v\($0)" }
        }
        return SoundPack(id: id, displayName: name, files: files)
    }
}

// MARK: - Loading (off the main thread only)

typealias SoundPackBuffers = [CosmeticEvent: [AVAudioPCMBuffer]]

enum SoundPackLoader {

    static func url(forFile name: String, packID: String, bundle: Bundle) -> URL? {
        bundle.url(forResource: name, withExtension: SoundPackCatalog.fileExtension)
            // Folder-reference layouts keep the subdirectory; support both.
            ?? bundle.url(forResource: name, withExtension: SoundPackCatalog.fileExtension,
                          subdirectory: "Sounds/\(packID)")
    }

    /// Reads every file of `pack` into PCM buffers in `format` (the engine's
    /// player format). Disk I/O + decoding: call on a background queue only.
    /// Events whose files are missing/undecodable are simply absent from the
    /// result; the engine then falls back to the default tone for them.
    static func decode(_ pack: SoundPack, format: AVAudioFormat, bundle: Bundle = .main) -> SoundPackBuffers {
        var out: SoundPackBuffers = [:]
        for (event, names) in pack.files {
            let buffers = names.compactMap { name -> AVAudioPCMBuffer? in
                guard let url = url(forFile: name, packID: pack.id, bundle: bundle) else { return nil }
                return decodeFile(at: url, to: format)
            }
            if !buffers.isEmpty { out[event] = buffers }
        }
        return out
    }

    /// One file → one buffer in `format`, converting sample rate / channel
    /// count if the file differs (the shipped files already match: 44.1 kHz mono).
    static func decodeFile(at url: URL, to format: AVAudioFormat) -> AVAudioPCMBuffer? {
        guard let file = try? AVAudioFile(forReading: url) else { return nil }
        let srcFormat = file.processingFormat
        let frames = AVAudioFrameCount(file.length)
        guard frames > 0,
              let src = AVAudioPCMBuffer(pcmFormat: srcFormat, frameCapacity: frames),
              (try? file.read(into: src)) != nil else { return nil }
        if srcFormat == format { return src }

        guard let converter = AVAudioConverter(from: srcFormat, to: format) else { return nil }
        let ratio = format.sampleRate / srcFormat.sampleRate
        let capacity = AVAudioFrameCount((Double(src.frameLength) * ratio).rounded(.up)) + 64
        guard let dst = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: capacity) else { return nil }
        var fed = false
        var error: NSError?
        let status = converter.convert(to: dst, error: &error) { _, inputStatus in
            if fed {
                inputStatus.pointee = .endOfStream
                return nil
            }
            fed = true
            inputStatus.pointee = .haveData
            return src
        }
        guard status != .error, error == nil, dst.frameLength > 0 else { return nil }
        return dst
    }
}
